    /// Closed polygons as one path, scaled from source pixels.
    static func path(_ loops: [[CGFloat]], scale: CGFloat, dx: CGFloat = 0) -> CGPath {
        let path = CGMutablePath()
        for loop in loops where loop.count >= 6 {
            path.move(to: CGPoint(x: (loop[0] + dx) * scale, y: loop[1] * scale))
            for i in stride(from: 2, to: loop.count - 1, by: 2) {
                path.addLine(to: CGPoint(x: (loop[i] + dx) * scale, y: loop[i + 1] * scale))
            }
            path.closeSubpath()
        }
        return path
    }
